Here's the implementation:

```tsx
// ErrorBoundary.tsx
import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary]", error.message, {
      stack: error.stack,
      componentStack: info.componentStack,
    });
  }

  retry = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      return fallback ? (
        fallback(error, this.retry)
      ) : (
        <DefaultFallback error={error} retry={this.retry} />
      );
    }

    return children;
  }
}

function DefaultFallback({ error, retry }: { error: Error; retry: () => void }) {
  return (
    <div role="alert" style={{ padding: "1rem", border: "1px solid #f00" }}>
      <h2>Something went wrong</h2>
      <pre style={{ fontSize: "0.85em", color: "#c00" }}>{error.message}</pre>
      <button onClick={retry}>Retry</button>
    </div>
  );
}
```

**Usage:**

```tsx
// Basic — uses default fallback UI
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary
  fallback={(error, retry) => (
    <div>
      <p>Error: {error.message}</p>
      <button onClick={retry}>Try again</button>
    </div>
  )}
>
  <MyComponent />
</ErrorBoundary>
```

**Key design decisions:**

| Decision | Reason |
|---|---|
| Class component | `getDerivedStateFromError` / `componentDidCatch` have no hook equivalents |
| `retry` resets state to `null` | Re-renders children; if the error was transient (e.g. a failed fetch), it recovers cleanly |
| `fallback` prop as render function | Gives callers access to `error` and `retry` without extra context plumbing |
| `role="alert"` on default UI | Screen readers announce the error immediately |

Note: retry only works if the underlying cause is gone — wrap data-fetching children in something like `react-query` or a `key` prop reset if you need forced remounting.
